import forgelib as F
G = F.make(slug="the-forge-island-3-guide", order=21, kw="the forge island 3",
 title="The Forge Island 3 Guide: Frostspire Expanse (Winter)",
 h1="The Forge Island 3 Guide: How to Complete the Frostspire Expanse (Winter Expansion)",
 desc="The Forge Island 3 guide: how to unlock the Frostspire Expanse, Bjorn's and Moro's quests, the Geyser shortcut, The Peak, Golem boss times and top ores.",
 kw2=["the forge island 3","the forge frostspire expanse","the forge winter expansion","how to get to island 3 the forge","the forge world 3"],
 related=["the-forge-prismatic-pickaxe","the-forge-raven-cave","the-forge-heavenly-pickaxe","the-forge-christmas-event"],
 ids=["zjjd760Nrgk","s7TJy8BU8-w"],
 lead="<strong>The Forge Island 3</strong>, the Frostspire Expanse, arrived with the Winter Expansion on December 25, 2025, as version 1.02. Fridge posted a walkthrough that day and a full guide the next. Here's how to unlock it and what to do there, checked against the Forge Wiki.",
 heading="Watch Fridge's Island 3 Videos",
 sections=[
 ("unlock","How to Unlock Island 3","""<ol class="steps"><li>Reach <strong>level 70</strong>. Pro Game Guides lists 70+ as the requirement.</li><li>Use the Wizard's <strong>portal</strong> to travel to the Frostspire Expanse.</li><li>Start Bjorn's questline with <em>Getting to Island 3</em>: meet <strong>Bjorn</strong>, who stands up the path to the left of the docks.</li></ol>"""),
 ("priority","Quests to Do First","""<p>The Forge Island 3 quests aren't equal. Here is the Forge Wiki's priority list for World 3:</p>
<ol><li><strong>Sensei Moro's questline</strong> (top priority). It also unlocks better shop pickaxes.</li><li><strong>Bjorn's questline</strong> (top priority). It ends with the Golem boss.</li><li><strong>Angel's questline and Masked Stranger</strong> (high). These are quick money, and you can do them together because they share targets.</li><li><strong>Raven questline</strong> (high). It unlocks the Raven Cave and Raven armor. See our <a href="the-forge-raven-cave.html">Raven Cave guide</a>.</li><li><strong>Goblin Lord</strong> (low). See the <a href="the-forge-goblin-lord-quest.html">Goblin Lord quest guide</a>.</li></ol>"""),
 ("places","Key Locations on the Frostspire Expanse","""<div class="table-wrap"><table><caption>Frostspire Expanse locations (Forge Wiki)</caption><thead><tr><th scope="col">Location</th><th scope="col">What's there</th></tr></thead><tbody>
<tr><td>Frostspire Geyser</td><td>A fast-travel launch to The Peak, unlocked with the <em>Melting the Geyser</em> quest</td></tr>
<tr><td>Frost Webs / The Frost Nest</td><td>The spider cave and nest, home of the Prismarine Spider</td></tr>
<tr><td>The Peak</td><td>The high-level summit, with Floating Crystals and Divine ores</td></tr>
<tr><td>Colossal Gate</td><td>Golem boss arena, open XX:00–XX:15 and XX:30–XX:45</td></tr>
<tr><td>Raven Cave</td><td>The Crimson Depths, plus Corruption's Heart below</td></tr>
<tr><td>Ferry and Secret Maze</td><td>The angels, the Heavenly Pickaxe and Fungi's Shop</td></tr>
<tr><td>The Iceberg</td><td>Mosasaursit and the Prismatic Pickaxe</td></tr></tbody></table></div>
<p>Pro Game Guides describes the Geyser shortcut as a frozen cannon that the <strong>Ice Man</strong> unfreezes once you bring him <strong>1 Demonite, 3 Fireite and 5 Magmaite</strong>. Save those from Island 2.</p>"""),
 ("golem","The Golem Boss","""<p>The Golem is an ancient Ice Titan and the first boss added to the game. Its 25,000 HP scales with party size, and it has four attacks. It gives 15,000–30,000 Gold and 3,500 XP, and it can drop Golem Heart (1 in 8), Armor Molds, Miner Shards and Raid Tickets. Fighting tips are in our <a href="the-forge-combat-guide.html">combat guide</a>.</p>"""),
 ("ores","Best Island 3 Ores","""<p>The rarest Frostspire ores include <strong>Heavenite</strong> and <strong>Gargantuan</strong> (Divine), <strong>Golem Heart</strong> and <strong>Stolen Heart</strong> (Divine), <strong>Suryafal</strong> and <strong>Heart of the Island</strong> (Relic), and <strong>Iceite</strong>, <strong>Etherealite</strong>, <strong>Duranite</strong> and <strong>Yeti Heart</strong> (Mythic). You'll need at least a Void Pickaxe for The Peak's crystals, then upgrade to the <a href="the-forge-prismatic-pickaxe.html">Prismatic Pickaxe</a>. With that, you're set for the rest of The Forge Island 3 content, from the Raven Cave to the Secret Maze.</p>""")],
 faq=[("How do you get to Island 3 in The Forge?","Reach level 70, then use the Wizard's portal to travel to the Frostspire Expanse."),
      ("When does the Golem boss spawn in The Forge?","The Colossal Gate opens from XX:00 to XX:15 and from XX:30 to XX:45 every hour."),
      ("What should I do first on Island 3?","Sensei Moro's and Bjorn's questlines, which the Forge Wiki rates top priority.")],
 sources=[F.wiki("Frostspire_Expanse","Frostspire Expanse"),F.wiki("Getting_to_Island_3","Getting to Island 3"),F.wiki("Golem","Golem boss"),F.wiki("Guide","Community guide: quest priority"),F.wiki("Version_History","Version History"),("Pro Game Guides: Frostspire Expanse POIs and level requirements","https://progameguides.com/roblox/the-forge-map-all-islands-locations-level-requirements/")],
 howto=("How to unlock Island 3 in The Forge",[("Reach level 70","Level up on the Forgotten Kingdom.","unlock"),("Use the portal","Travel to the Frostspire Expanse through the Wizard's portal.","unlock"),("Meet Bjorn","Start Getting to Island 3 by talking to Bjorn.","unlock")]))
